#include <esp_log.h>\n#include <nvs_flash.h>\n#include <esp_matter.h>\n#include <esp_matter_core.h>\n#include <app/server/Server.h>\n\n#include "led_driver.h"\n#include "button_handler.h"\n#include "temperature_monitor.h"\n#include "matter_endpoint_config.h"\n#include "wifi_monitor.h"\n#include "nvs_storage.h"\n#include "ota_handler.h"\n\nstatic const char *TAG = "MAIN";\n\nextern "C" void app_main() {\n    ESP_LOGI(TAG, "Initializing RGB Smart Bulb Firmware...");\n\n    // 1. Initialize NVS (required for Wi-Fi and Matter)\n    esp_err_t err = nvs_flash_init();\n    if (err == ESP_ERR_NVS_NO_FREE_PAGES || err == ESP_ERR_NVS_NEW_VERSION_FOUND) {\n        ESP_ERROR_CHECK(nvs_flash_erase());\n        err = nvs_flash_init();\n    }\n    ESP_ERROR_CHECK(err);\n\n    // 2. Initialize Hardware Drivers\n    led_driver_init();\n    temperature_monitor_init();\n    button_handler_init();\n    \n    // 3. Restore Last Known State\n    nvs_storage_state_t last_state;\n    if (nvs_storage_load_state(&last_state) == ESP_OK) {\n        ESP_LOGI(TAG, "Restored state: On=%d, Bri=%d, RGB=(%d,%d,%d)", \n            last_state.is_on, last_state.brightness, last_state.r, last_state.g, last_state.b);\n        if (last_state.is_on) {\n            led_driver_set_rgb(last_state.r, last_state.g, last_state.b);\n            led_driver_set_brightness(last_state.brightness);\n        }\n    }\n\n    // 4. Initialize ESP-Matter Core\n    esp_matter::node::config_t node_config;\n    esp_matter::node_t *node = esp_matter::node::create(&node_config, matter_endpoint_attribute_update_cb, matter_endpoint_identification_cb);\n    if (!node) {\n        ESP_LOGE(TAG, "Failed to create Matter node");\n        return;\n    }\n\n    // 5. Setup Matter Endpoints (Lighting, OTA, Diagnostics)\n    matter_endpoint_setup(node);\n\n    // 6. Start Matter Stack\n    err = esp_matter::start(matter_endpoint_event_cb);\n    if (err != ESP_OK) {\n        ESP_LOGE(TAG, "Failed to start Matter, err:%d", err);\n    }\n\n    // 7. Initialize Background Monitors\n    wifi_monitor_init();\n    ota_handler_init();\n\n    ESP_LOGI(TAG, "Device fully initialized and running.");\n}\n
